using MediatR;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using VetCommission.Application.Features.CommissionConfiguration;using VetCommission.WebApi.Auth;using VetCommission.WebApi.Extensions;namespace VetCommission.WebApi.Controllers;[ApiController,Route("api/competencias"),Authorize(Policy=AuthorizationPolicyNames.CompetenciesManage)]public sealed class CommissionConfigurationController(IMediator m):ControllerBase{[HttpGet]public async Task<IActionResult>List([FromQuery]int page=1,[FromQuery]int pageSize=20,CancellationToken c=default)=>(await m.Send(new ListCompetenciesQuery(page,pageSize),c)).ToActionResult(this);[HttpPost]public async Task<IActionResult>Save(SaveCompetencyCommand x,CancellationToken c)=>(await m.Send(x,c)).ToActionResult(this);[HttpPost("{id:guid}/fechar")]public async Task<IActionResult>Close(Guid id,CancellationToken c)=>(await m.Send(new SetCompetencyClosedCommand(id,true),c)).ToActionResult(this);[HttpGet("{id:guid}/regras"),Authorize(Policy=AuthorizationPolicyNames.CommissionRulesManage)]public async Task<IActionResult>Rules(Guid id,CancellationToken c)=>(await m.Send(new ListCommissionRulesQuery(id),c)).ToActionResult(this);[HttpPost("{id:guid}/regras"),Authorize(Policy=AuthorizationPolicyNames.CommissionRulesManage)]public async Task<IActionResult>SaveRule(Guid id,SaveRuleRequest x,CancellationToken c)=>(await m.Send(new SaveCommissionRuleCommand(x.Id,id,x.ProcedureId,x.RuleType,x.Percentage,x.FixedValue),c)).ToActionResult(this);public sealed record SaveRuleRequest(Guid? Id,Guid ProcedureId,string RuleType,decimal? Percentage,decimal? FixedValue);}
